async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('https://api.example.com/api/analytics').then(r => r.json()),
      fetch('https://api.example.com/api/notifications').then(r => r.json()),
      fetch('https://api.example.com/api/settings').then(r => r.json())
    ]);

    return { analytics, notifications, settings };
  } catch (error) {
    // Return mock data for build time or error cases
    return {
      analytics: { visits: 1250, bounceRate: '15%' },
      notifications: [
        { id: 1, text: 'New user registered' },
        { id: 2, text: 'Server usage high' }
      ],
      settings: { theme: 'dark', version: '1.0.2' }
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        <ul>
          <li>Visits: {analytics.visits}</li>
          <li>Bounce Rate: {analytics.bounceRate}</li>
        </ul>
      </section>

      <section>
        <h3>Notifications</h3>
        <ul>
          {notifications.map((n: any) => (
            <li key={n.id}>{n.text}</li>
          ))}
        </ul>
      </section>

      <section>
        <h3>Settings</h3>
        <p>Theme: {settings.theme}</p>
        <p>Version: {settings.version}</p>
      </section>
    </div>
  );
}

